{"content":""""Extra verification for ledger.apply_batch. Kept outside the repo tree."""

import sys
import traceback
from collections import OrderedDict, defaultdict, Counter
from collections.abc import Mapping
from types import MappingProxyType

sys.path.insert(0, "/tmp/workspace")
from ledger import apply_batch  # noqa: E402

CHECKS = []


def check(fn):
    CHECKS.append(fn)
    return fn


def expect_raises(exc_types, fn, *args, **kwargs):
    try:
        result = fn(*args, **kwargs)
    except exc_types as exc:
        return exc
    except BaseException as exc:  # noqa: BLE001
        raise AssertionError(
            "expected {} but got {}: {}".format(exc_types, type(exc).__name__, exc)
        ) from None
    raise AssertionError(
        "expected {} but call returned {!r}".format(exc_types, result)
    )


@check
def public_behaviour():
    s = {"a": 5}
    assert apply_batch(s, [("add", "a", 2)])["a"] == 7


@check
def add_semantics():
    s = {"a": 5}
    r = apply_batch(s, [("add", "a", 2), ("add", "b", 3), ("add", "a", 1)])
    assert r == {"a": 8, "b": 3}, r
    assert s == {"a": 5}, s
    assert r is not s
    assert apply_batch({}, [("add", "x", 10)]) == {"x": 10}
    assert apply_batch({"x": 1}, [("add", "x", 10**30)]) == {"x": 1 + 10**30}


@check
def sub_semantics():
    s = {"a": 5, "b": 1}
    r = apply_batch(s, [("sub", "a", 2), ("sub", "b", 1)])
    assert r == {"a": 3, "b": 0}, r
    assert s == {"a": 5, "b": 1}, s
    # sub to exactly zero is legal; one more is not
    assert apply_batch({"a": 4}, [("sub", "a", 4)]) == {"a": 0}


@check
def input_never_mutated_on_success():
    s = {"a": 5}
    snapshot = dict(s)
    r = apply_batch(s, [("add", "a", 1), ("sub", "a", 2), ("add", "z", 1)])
    assert s == snapshot
    # mutating the result must not affect the input
    r["a"] = 999
    r["new"] = 1
    assert s == snapshot


@check
def empty_ops_returns_equal_copy():
    s = {"a": 5}
    r = apply_batch(s, [])
    assert r == s and r is not s


@check
def atomicity_on_invalid_late_op():
    cases = [
        [("add", "a", 1), ("mul", "a", 1)],
        [("add", "a", 1), ("sub", "a", 99)],
        [("sub", "missing", 1), ("add", "a", 1)],
        [("add", "a", 1), ("add", "a", 0)],
        [("add", "a", 1), ("add", "a", -5)],
        [("add", "a", 1), ("add", "a", 1.5)],
        [("add", "a", 1), ("add", "a", True)],
        [("add", "a", 1), ("add", "a", "2")],
        [("add", "a", 1), ("bogus",)],
        [("add", "a", 1), "bogus"],
        [("add", "a", 1), ("add", "a", 1, 1)],
        [("add", "a", 1), None],
        [("add", "a", 1), ("add", ["unhashable"], 1)],
    ]
    for ops in cases:
        s = {"a": 5, "b": 7}
        snapshot = dict(s)
        expect_raises((ValueError, KeyError), apply_batch, s, ops)
        assert s == snapshot, (ops, s)
    # single-op variants raise too and still leave the input alone
    for ops in [
        [("mul", "a", 1)],
        [("ADD", "a", 1)],
        [("", "a", 1)],
        [(None, "a", 1)],
        [(7, "a", 1)],
        [("sub", "nope", 1)],
        [("sub", "a", 6)],
        [("add", "a", 0)],
        [("add", "a", -1)],
        [("sub", "a", -1)],
        [("add", "a", 2.0)],
        [("add", "a", False)],
        [("add", "a", None)],
    ]:
        s = {"a": 5}
        snapshot = dict(s)
        expect_raises((ValueError, KeyError), apply_batch, s, ops)
        assert s == snapshot, (ops, s)


@check
def error_types_are_specific():
    # unknown op -> ValueError
    expect_raises(ValueError, apply_batch, {"a": 1}, [("transfer", "a", 1)])
    # missing sub key -> KeyError whose args carry the key
    exc = expect_raises(KeyError, apply_batch, {"a": 1}, [("sub", "ghost", 1)])
    assert exc.args == ("ghost",), exc.args
    # negative result -> ValueError
    expect_raises(ValueError, apply_batch, {"a": 1}, [("sub", "a", 2)])
    # bad amounts -> ValueError
    for bad in (0, -3, 1.5, 2.0, True, False, "1", None, 3 + 0j):
        expect_raises(ValueError, apply_batch, {"a": 1}, [("add", "a", bad)])
        expect_raises(ValueError, apply_batch, {"a": 1}, [("sub", "a", bad)])


@check
def mapping_types_and_keys():
    # arbitrary hashable keys
    r = apply_batch({1: 5, (2, 3): 1}, [("add", 1, 1), ("add", (2, 3), 1), ("add", None, 4)])
    assert r == {1: 6, (2, 3): 2, None: 4}, r

    for state in (
        OrderedDict(a=1),
        defaultdict(int, a=1),
        Counter(a=1),
        MappingProxyType({"a": 1}),
        {"a": 1},
    ):
        before = dict(state)
        r = apply_batch(state, [("add", "a", 4)])
        assert r["a"] == 5, (type(state), r)
        assert dict(state) == before, (type(state), state)
        assert r is not state

    class Duck(Mapping):
        def __init__(self, data):
            self._d = dict(data)

        def __getitem__(self, k):
            return self._d[k]

        def __iter__(self):
            return iter(self._d)

        def __len__(self):
            return len(self._d)

    duck = Duck({"a": 2})
    r = apply_batch(duck, [("add", "a", 3)])
    assert r == {"a": 5} and duck == {"a": 2}


@check
def generators_and_tuples():
    ops = (op for op in [("add", "a", 1), ("sub", "a", 1)])
    assert apply_batch({"a": 5}, ops) == {"a": 5}
    # a single bare tuple is iterated as ops entries -> ValueError, input safe
    s = {"a": 5}
    expect_raises(ValueError, apply_batch, s, ("add", "a", 1))
    assert s == {"a": 5}


@check
def bad_state_argument():
    expect_raises(TypeError, apply_batch, None, [("add", "a", 1)])
    expect_raises(TypeError, apply_batch, 42, [("add", "a", 1)])


@check
def many_ops_linear():
    # smoke: 50k ops stay correct and cumulative
    ops = [("add", "a", 1)] * 50000
    assert apply_batch({"a": 0}, ops) == {"a": 50000}
    ops = [("add", "a", 1), ("sub", "a", 1)] * 25000
    assert apply_batch({"a": 0}, ops) == {"a": 0}


def main():
    failures = 0
    for fn in CHECKS:
        try:
            fn()
        except BaseException:  # noqa: BLE001
            failures += 1
            print("FAIL: {}".format(fn.__name__))
            traceback.print_exc()
        else:
            print("ok  : {}".format(fn.__name__))
    print("---")
    print("{} checks, {} failures".format(len(CHECKS), failures))
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
